function assertServerlessArticle(source) {
  assert.deepEqual(parseFrontMatter(source), EXACT_METADATA, 'exact STY-11 front matter');
  const headings = findMarkdownHeadings(source);
  assert.deepEqual(headings.filter(({level}) => level === 2).map(({text}) => text), EXPECTED_HEADINGS, 'exact H2 order');
  const migration = headings.find(({level, text}) => level === 2 && text === '可迁移经验');
  const next = headings.find(({level, offset}) => level === 2 && offset > migration.offset);
  assert.deepEqual(headings.filter(({level, offset}) => level === 3 && offset > migration.offset && (!next || offset < next.offset)).map(({text}) => text), MIGRATION_HEADINGS, 'exact migration H3 order');
  for (const label of WRAPPERS) assert.match(source, new RegExp('<div\\b(?=[^>]*role="region")(?=[^>]*aria-label="' + escapeRegExp(label) + '")(?=[^>]*tabIndex=\\{0\\})(?=[^>]*onKeyDown=\\{handleHorizontalArrowKey\\})[^>]*>', 'u'), label + ' keyboard scroll wrapper');
  assert.equal((source.match(/role="region"/gu) ?? []).length, 4, 'exactly four wrappers');
  assert.deepEqual(table(source, ['构件', '正向责任', '持久事实', '明确不拥有']).slice(2), OWNERSHIP_ROWS, 'exact ownership table');
  assert.deepEqual(table(source, ['故障', '检测', '自动响应', '停止条件', '最终责任人']).slice(2), FAILURE_ROWS, 'exact failure table');
  assert.deepEqual(table(source, ['观察', '先验证', '首选动作', '升级条件']).slice(2), COLD_COST_ROWS, 'exact cold-start/cost table');
  includesOrdered(source, ORDER_FLOW, 'nine-step order flow'); includesOrdered(source, CONCURRENCY_LAYERS, 'three concurrency budgets');
  for (const value of ['入口幂等键', '订单操作标识', '步骤操作标识', '事件标识']) assert.match(source, new RegExp(escapeRegExp(value), 'u'), value + ' visible boundary');
  includesOrdered(source, ['必须保持可导出', '可以合理适配', '可以明确绑定'], 'vendor boundaries');
  includesOrdered(source, ['导出当前订单状态与未完成操作', '冻结新流程版本', '暂停或排空旧消费者', '迁移事件合同、幂等身份和外部回执', '在新执行面恢复未完成步骤', '验证旧事件或迟到结果不会覆盖新状态', '撤销旧触发器、凭证和写权限'], 'exit drill');
  for (const unsafe of ['函数内存作为业务状态', '同步等待整条履约链', '队列就是成功', '事件标识就是业务幂等', '盲目重放', '函数扩容决定库存', '下游预算高于权威容量', '无限重试不受限制', '关键步骤失败开放', '通知回滚已确认订单', '毒消息重试', '默认预热', '只比较价格', '人工负责人待定', 'CloudEvents意味着投递', '工作流 DSL 意味着运行时等价', '强制可移植适配', '只迁移函数']) assert.doesNotMatch(source, new RegExp(escapeRegExp(unsafe), 'u'), unsafe + ' is rejected');
}

function fixtureArticle() {
  const front = frontMatterFixture(EXACT_METADATA);
  const sections = EXPECTED_HEADINGS.map((heading) => '## ' + heading + (heading === '可迁移经验' ? '\n### ' + MIGRATION_HEADINGS.join('\n### ') : '')).join('\n');
  const wrappers = WRAPPERS.map((label) => exactWrapper(label)).join('\n');
  const ownership = OWNERSHIP_ROWS.map((row) => '| ' + row.join(' | ') + ' |').join('\n');
  const failures = FAILURE_ROWS.map((row) => '| ' + row.join(' | ') + ' |').join('\n');
  const cost = COLD_COST_ROWS.map((row) => '| ' + row.join(' | ') + ' |').join('\n');
  return '---\n' + front + '\n---\n' + sections + '\n' + wrappers + '\n| 构件 | 正向责任 | 持久事实 | 明确不拥有 |\n| --- | --- | --- | --- |\n' + ownership + '\n' + ORDER_FLOW.join('\n') + '\n' + CONCURRENCY_LAYERS.join('\n') + '\n入口幂等键、订单操作标识、步骤操作标识与事件标识。\n| 故障 | 检测 | 自动响应 | 停止条件 | 最终责任人 |\n| --- | --- | --- | --- | --- |\n' + failures + '\n\n| 观察 | 先验证 | 首选动作 | 升级条件 |\n| --- | --- | --- | --- |\n' + cost + '\n必须保持可导出\n可以合理适配\n可以明确绑定\n导出当前订单状态与未完成操作\n冻结新流程版本\n暂停或排空旧消费者\n迁移事件合同、幂等身份和外部回执\n在新执行面恢复未完成步骤\n验证旧事件或迟到结果不会覆盖新状态\n撤销旧触发器、凭证和写权限';
}

test('STY-11 helper and mutation fixtures lock the approved content contract', () => {
  const fixture = fixtureArticle(); assertServerlessArticle(fixture);
  for (const key of Object.keys(EXACT_METADATA)) { assert.throws(() => assertServerlessArticle(removeFrontMatterField(fixture, key)), assert.AssertionError, key + ' deletion rejected'); assert.throws(() => assertServerlessArticle(changeFrontMatterField(fixture, key)), assert.AssertionError, key + ' changed rejected'); }
  for (const heading of [...EXPECTED_HEADINGS, ...MIGRATION_HEADINGS]) { const token = (MIGRATION_HEADINGS.includes(heading) ? '### ' : '## ') + heading; assert.throws(() => assertServerlessArticle(replaceOnce(fixture, token, '', heading)), assert.AssertionError, heading + ' deletion rejected'); assert.throws(() => assertServerlessArticle(replaceOnce(fixture, token, token + '（变更）', heading)), assert.AssertionError, heading + ' changed rejected'); }
  for (const label of WRAPPERS) for (const [from, to] of [['role="region"', 'role="table"'], ['tabIndex={0}', 'tabIndex={-1}'], ['onKeyDown={handleHorizontalArrowKey}', 'onKeyDown={undefined}']]) assert.throws(() => assertServerlessArticle(replaceOnce(fixture, from, to, label)), assert.AssertionError, label + ' wrapper mutation rejected');
  for (const rows of [OWNERSHIP_ROWS, FAILURE_ROWS, COLD_COST_ROWS]) for (const row of rows) for (let index = 0; index < row.length; index += 1) { const changed = [...row]; changed[index] = '错误的合同值'; assert.throws(() => assertServerlessArticle(replaceOnce(fixture, '| ' + row.join(' | ') + ' |', '| ' + changed.join(' | ') + ' |', row[0])), assert.AssertionError, row[0] + ' cell mutation rejected'); }
  for (const unsafe of ['函数内存作为业务状态', '同步等待整条履约链', '队列就是成功', '无限重试不受限制', '默认预热', '只比较价格', '只迁移函数']) assert.throws(() => assertServerlessArticle(fixture + '\n' + unsafe), assert.AssertionError, unsafe + ' rejected');
});

test('STY-11 source fixture locks the eleven identities and citation roles', () => {
  const remote = SOURCE_IDS.slice(0, -1); const ledger = {sources: SOURCE_IDS.map((id) => ({id})), documents: {[ARTICLE]: {citations: [...remote.map((source_id, index) => ({source_id, manifest_primary: index === 0, usage_mode: 'facts-summary'})), {source_id: SOURCE_IDS.at(-1), manifest_primary: false, usage_mode: 'original-illustration'}]}}};
  const citations = ledger.documents[ARTICLE].citations; assert.equal(citations.length, 11); assert.equal(citations.filter(({source_id}) => source_id !== SOURCE_IDS.at(-1)).length, 10); assert.deepEqual(citations.filter(({manifest_primary}) => manifest_primary).map(({source_id}) => source_id), ['src-cncf-serverless-whitepaper-v1']); assert.equal(citations.at(-1).usage_mode, 'original-illustration');
  for (const id of SOURCE_IDS) assert.ok(ledger.sources.some((source) => source.id === id), id + ' exists');
  const changed = structuredClone(ledger); changed.documents[ARTICLE].citations[0].manifest_primary = false; changed.documents[ARTICLE].citations[1].manifest_primary = true; assert.notDeepEqual(changed.documents[ARTICLE].citations.filter(({manifest_primary}) => manifest_primary).map(({source_id}) => source_id), ['src-cncf-serverless-whitepaper-v1'], 'primary mutation applies');
});

test('STY-11 implementation remains RED until its article, sources, relations, diagram, and projection exist', () => {
  const source = file(ARTICLE); assert.ok(source, ARTICLE + ' must exist after implementation');
  assertServerlessArticle(source);
  const ledger = JSON.parse(readFileSync('data/source-ledger.json', 'utf8')); assert.ok(ledger.documents?.[ARTICLE], 'STY-11 source ledger entry');
  const diagram = file(DRAWIO); const svg = file(SVG); assert.ok(diagram && svg, 'STY-11 diagram pair');
  for (const path of ['content/styles/sty-06-event-driven-architecture.mdx', 'content/styles/sty-09-pipe-and-filter-architecture.mdx', 'content/cases/cloudflare-durable-objects-workerd.mdx']) assert.match(file(path), new RegExp(escapeRegExp(ROUTE), 'u'), path + ' reciprocal link');
  const projection = JSON.parse(readFileSync('src/generated/project-status.json', 'utf8')); assert.deepEqual({completed: projection.completed_topics, documents: projection.content_documents, sources: projection.governed_sources}, EXPECTED_STAGE_A, 'Stage A projection');
});
